const schoolSummary = `-- name: SchoolSummary :one
SELECT
  COALESCE((SELECT sum(total_minor) FROM fin_invoices WHERE school_id = $1::bigint AND status <> 'void' AND currency = $2::text), 0)::bigint AS billed_minor,
  COALESCE((SELECT sum(amount_minor) FROM fin_payments WHERE school_id = $1::bigint AND status = 'successful' AND currency = $2::text), 0)::bigint AS collected_minor,
  COALESCE((SELECT sum(e.debit_minor - e.credit_minor) FROM fin_entries e JOIN fin_accounts a ON a.id = e.account_id
            WHERE a.school_id = $1::bigint AND a.code = '1100' AND e.currency = $2::text), 0)::bigint AS outstanding_minor,
  (SELECT count(*) FROM fin_payments WHERE school_id = $1::bigint AND status = 'pending')::bigint AS pending_payments
`

type SchoolSummaryParams struct {
	SchoolID int64
	Currency string
}

type SchoolSummaryRow struct {
	BilledMinor      int64
	CollectedMinor   int64
	OutstandingMinor int64
	PendingPayments  int64
}

func (q *Queries) SchoolSummary(ctx context.Context, arg SchoolSummaryParams) (SchoolSummaryRow, error) {
	row := q.db.QueryRow(ctx, schoolSummary, arg.SchoolID, arg.Currency)
	var i SchoolSummaryRow
	err := row.Scan(
		&i.BilledMinor,
		&i.CollectedMinor,
		&i.OutstandingMinor,
		&i.PendingPayments,
	)
	return i, err
}

