const studentStatement = `-- name: StudentStatement :many

SELECT j.created_at, j.kind, j.reference, j.memo, e.currency, e.debit_minor, e.credit_minor
FROM fin_entries e
JOIN fin_journals j ON j.id = e.journal_id
JOIN fin_accounts a ON a.id = e.account_id
WHERE a.school_id = $1 AND a.code = '1100' AND e.student_id = $2
ORDER BY j.created_at, j.id
`

type StudentStatementParams struct {
	SchoolID  int64
	StudentID pgtype.Int8
}

type StudentStatementRow struct {
	CreatedAt   pgtype.Timestamptz
	Kind        string
	Reference   string
	Memo        string
	Currency    string
	DebitMinor  int64
	CreditMinor int64
}

// ---- statements and reports ------------------------------------------------------------
// The student's fees account at one school: charges are debits, payments credits.
func (q *Queries) StudentStatement(ctx context.Context, arg StudentStatementParams) ([]StudentStatementRow, error) {
	rows, err := q.db.Query(ctx, studentStatement, arg.SchoolID, arg.StudentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []StudentStatementRow{}
	for rows.Next() {
		var i StudentStatementRow
		if err := rows.Scan(
			&i.CreatedAt,
			&i.Kind,
			&i.Reference,
			&i.Memo,
			&i.Currency,
			&i.DebitMinor,
			&i.CreditMinor,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
